class Solution { int[] parent,size;private int find(int value){while(value!=parent[value]){parent[value]=parent[parent[value]];value=parent[value];}return value;}private void union(int a,int b){a=find(a);b=find(b);if(a==b)return;if(size[a]<size[b]){int temporary=a;a=b;b=temporary;}parent[b]=a;size[a]+=size[b];}public int latestDayToCross(int row,int col,int[][] cells){int total=row*col,top=total,bottom=total+1;parent=new int[total+2];size=new int[total+2];for(int i=0;i<parent.length;i++){parent[i]=i;size[i]=1;}boolean[] land=new boolean[total];int[][] directions={{1,0},{-1,0},{0,1},{0,-1}};for(int day=cells.length-1;day>=0;day--){int r=cells[day][0]-1,c=cells[day][1]-1,index=r*col+c;land[index]=true;if(r==0)union(index,top);if(r==row-1)union(index,bottom);for(int[] direction:directions){int nr=r+direction[0],nc=c+direction[1];if(nr>=0&&nr<row&&nc>=0&&nc<col&&land[nr*col+nc])union(index,nr*col+nc);}if(find(top)==find(bottom))return day;}return 0;} }
